"""Phase 0: compute expected payouts per policy and diff against payout_lines.csv.

Run: python scripts/analyze_data.py
"""
from __future__ import annotations

import csv
import json
import sys
from collections import Counter, defaultdict
from datetime import date, datetime, timedelta, timezone
from decimal import ROUND_HALF_UP, Decimal
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DATA = ROOT / "data"

IST = timezone(timedelta(hours=5, minutes=30))


def ist_day(ts: str) -> date:
    """2026-09-12T02:30:00Z -> IST calendar day."""
    dt = ts.strip()
    if dt.endswith("Z"):
        dt = dt[:-1] + "+00:00"
    parsed = datetime.fromisoformat(dt)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(IST).date()


def trip_fare(distance_km: Decimal, surge: Decimal) -> int:
    raw = (Decimal(25) + Decimal(6) * max(Decimal(0), distance_km - Decimal(2))) * surge
    return int(raw.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def main() -> None:
    riders = list(csv.DictReader(open(DATA / "riders.csv")))
    trips = list(csv.DictReader(open(DATA / "trips.csv")))
    lines = list(csv.DictReader(open(DATA / "payout_lines.csv")))

    print(f"riders={len(riders)} trips={len(trips)} lines={len(lines)}")
    print("trip status counts:", Counter(t["status"] for t in trips))
    print("surge multiplier values:", Counter(t["surge_multiplier"] for t in trips))
    print("penalty line amounts:", Counter(l["amount"] for l in lines if l["line_type"] == "cancellation_penalty"))
    print("incentive line amounts:", Counter(l["amount"] for l in lines if l["line_type"] == "daily_incentive"))

    trips_by_id = {t["trip_id"]: t for t in trips}
    trip_lines = {}
    penalties = defaultdict(list)   # (rider, day) -> [line]
    incentives = defaultdict(list)
    orphan_trip_lines = 0
    for ln in lines:
        rid, pd = ln["rider_id"], date.fromisoformat(ln["payout_date"])
        if ln["line_type"] == "trip":
            trip_lines[ln["trip_id"]] = ln
            if ln["trip_id"] not in trips_by_id:
                orphan_trip_lines += 1
        elif ln["line_type"] == "cancellation_penalty":
            penalties[(rid, pd)].append(ln)
        elif ln["line_type"] == "daily_incentive":
            incentives[(rid, pd)].append(ln)
    print("orphan trip lines (trip_id not in trips.csv):", orphan_trip_lines)

    # completed trips grouped by rider/day
    completed = defaultdict(list)
    for t in sorted(trips, key=lambda t: t["started_at"]):
        t["_ist_day"] = str(ist_day(t["started_at"]))
        if t["status"] == "completed":
            completed[(t["rider_id"], t["_ist_day"])].append(t)

    # per-trip fare diff
    fare_mismatch = []
    unpaid_completed = []
    duplicate_trip_lines = 0
    seen_trip_line = Counter()
    for tid, ln in trip_lines.items():
        seen_trip_line[tid] += 1
    for tid, n in seen_trip_line.items():
        if n > 1:
            duplicate_trip_lines += 1
    print("duplicate trip payout lines:", duplicate_trip_lines)

    for rid, day in sorted(completed):
        for t in completed[(rid, day)]:
            expected = trip_fare(Decimal(t["distance_km"]), Decimal(t["surge_multiplier"]))
            ln = trip_lines.get(t["trip_id"])
            if ln is None:
                unpaid_completed.append((rid, day, t["trip_id"], expected, None))
                continue
            actual = int(ln["amount"])
            if actual != expected:
                fare_mismatch.append(
                    {"rider": rid, "day": day, "trip": t["trip_id"], "expected": expected,
                     "actual": actual, "diff": expected - actual,
                     "dist": t["distance_km"], "surge": t["surge_multiplier"]}
                )

    print(f"\nUNPAID completed trips with no payout line: {len(unpaid_completed)}")
    for row in unpaid_completed:
        print("  UNPAID", row)
    print(f"\nFARE MISMATCHES (paid line amount != expected fare): {len(fare_mismatch)}")
    for m in fare_mismatch:
        print("  MISMATCH", m)

    # duplicate / missing penalties
    pen_issues = []
    for (rid, day), pls in sorted(penalties.items()):
        rider_cancels = sum(1 for t in trips_by_id.values() if t["rider_id"] == rid and t["status"] == "cancelled_by_rider" and t["_ist_day"] == str(day))
        if len(pls) != rider_cancels:
            amts = [l["amount"] for l in pls]
            pen_issues.append({"rider": rid, "day": str(day), "penalty_lines": len(pls),
                               "rider_cancels": rider_cancels, "amounts": amts})
    print(f"\nPENALTY LINE vs rider-cancel count mismatches: {len(pen_issues)}")
    for p in pen_issues:
        print("  PEN", p)

    # incentive: eligible but missing / ineligible but paid
    inc_issues = []
    for (rid, day), comp in sorted(completed.items()):
        n = len(comp)
        paid = len(incentives.get((rid, day), []))
        if n >= 12 and paid == 0:
            inc_issues.append({"rider": rid, "day": str(day), "trips": n, "issue": "MISSING incentive", "paid_lines": paid})
        if n < 12 and paid > 0:
            inc_issues.append({"rider": rid, "day": str(day), "trips": n, "issue": "paid WITHOUT eligibility", "paid_lines": paid})
        if n >= 12 and paid > 1:
            inc_issues.append({"rider": rid, "day": str(day), "trips": n, "issue": "DUPLICATE incentive", "paid_lines": paid})
    print(f"\nINCENTIVE issues: {len(inc_issues)}")
    for i in inc_issues:
        print("  INC", i)

    # --- scenario checks ---
    print("\n--- SCENARIO DIGEST ---")
    checks = [
        ("R003", sep(20), "whole-date scan: what would we find?"),
        ("R005", sep(21), "incentive"),
        ("R008", None, "trip T252921"),
        ("R014", sep(18), "penalty"),
        ("R016", sep(19), "missing payments"),
        ("R021", None, "trip T482410"),
        ("R022", sep(13), "surge"),
        ("R024", sep(18), "incentive"),
        ("R025", sep(19), "incentive"),
        ("R007", None, "trip T840677"),
        ("R009", sep(17), "incentive"),
        ("R026", None, "trip T672899"),
        ("R031", None, "trip T312538"),
        ("R033", sep(20), "missing payments"),
        ("R034", sep(19), "missing payments"),
        ("R035", sep(21), "named trip T980582 + surge on date"),
        ("R027", sep(20), "surge on date") ,
        ("R027", sep(21), "penalty on date"),
    ]
    trips_of = defaultdict(list)
    for t in trips:
        trips_of[t["rider_id"]].append(t)
    payout_trip_lines_grouped = defaultdict(list)
    for ln in lines:
        if ln["line_type"] == "trip":
            payout_trip_lines_grouped[ln["trip_id"]].append(ln)

    def trip_report(rid: str, tid: str) -> None:
        t = trips_by_id.get(tid)
        if not t:
            print(f"  {rid} {tid}: TRIP NOT FOUND IN trips.csv")
            return
        expected = trip_fare(Decimal(t["distance_km"]), Decimal(t["surge_multiplier"]))
        ln = payout_trip_lines_grouped.get(tid)
        actual = [int(x["amount"]) for x in ln] if ln else None
        print(f"  {rid} {tid}: status={t['status']} dist={t['distance_km']} surge={t['surge_multiplier']} "
              f"day={t.get('_ist_day')} expected={expected} paid={actual}")

    for rid, day, label in checks:
        if day is None or label.startswith("trip"):
            pass
        print(f"\n[{rid} {label}]")

    # print explicit blocks
    print("\n== R003 all findings on Sep 20 ==")
    for m in fare_mismatch:
        if m["rider"] == "R003":
            print("  fare mismatch:", m)
    for row in unpaid_completed:
        if row[0] == "R003":
            print("  unpaid:", row)
    n3 = len(completed.get(("R003", str(sep(20))), []))
    paid3 = len(incentives.get(("R003", sep(20)), []))
    print(f"  completed trips on day: {n3}, incentive lines: {paid3}")
    for p in pen_issues:
        if p["rider"] == "R003":
            print("  penalty:", p)

    print("\n== R035 findings on Sep 21 (whole-date scan risk) ==")
    for m in fare_mismatch:
        if m["rider"] == "R035" and m["day"] == str(sep(21)):
            print("  fare mismatch:", m)
    for row in unpaid_completed:
        if row[0] == "R035" and row[1] == str(sep(21)):
            print("  unpaid:", row)
    n5 = len(completed.get(("R035", str(sep(21))), []))
    print(f"  completed trips on day: {n5}")

    print("\n== R027 findings on Sep 20 (surge) and Sep 21 (penalty) ==")
    for m in fare_mismatch:
        if m["rider"] == "R027" and m["day"] in (str(sep(20)), str(sep(21))):
            print("  fare mismatch:", m)
    for p in pen_issues:
        if p["rider"] == "R027":
            print("  penalty:", p)

    print("\n== R016 findings on Sep 19 ==")
    for row in unpaid_completed:
        if row[0] == "R016" and row[1] == str(sep(19)):
            print("  unpaid:", row)
    for m in fare_mismatch:
        if m["rider"] == "R016":
            print("  other mismatch:", m)

    print("\n== R034 findings on Sep 19 ==")
    for row in unpaid_completed:
        if row[0] == "R034" and row[1] == str(sep(19)):
            print("  unpaid:", row)

    print("\n== trap riders full-date scan ==")
    for rid, day in (("R008", sep(21)), ("R009", sep(17)), ("R011", sep(19)), ("R025", sep(19)), ("R013", sep(22)), ("R021", sep(21)), ("R022", sep(13))):
        comp = completed.get((rid, str(day)), [])
        pays = [trip_lines[t["trip_id"]]["amount"] for t in comp if t["trip_id"] in trip_lines]
        inc = len(incentives.get((rid, day), []))
        pen = len(penalties.get((rid, day), []))
        print(f"  {rid} day={day}: completed={len(comp)} paid_lines={len(pays)} (amounts={pays[:8]}...) incentive_lines={inc} penalty_lines={pen}")

    # how many total discrepancies (whole dataset) for context
    print(f"\nTOTALS: fare_mismatch={len(fare_mismatch)} unpaid_completed={len(unpaid_completed)} "
          f"penalty_issues={len(pen_issues)} incentive_issues={len(inc_issues)}")


def sep(d: int) -> date:
    return date(2026, 9, d)


if __name__ == "__main__":
    main()

"""Phase 0 v2: policy diff with distance/rider normalization + keyed lookups fixed."""
from __future__ import annotations

import csv
import re
from collections import Counter, defaultdict
from datetime import date, datetime, timedelta, timezone
from decimal import ROUND_HALF_UP, Decimal
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DATA = ROOT / "data"
IST = timezone(timedelta(hours=5, minutes=30))


def ist_day(ts: str) -> date:
    dt = ts.strip()
    if dt.endswith("Z"):
        dt = dt[:-1] + "+00:00"
    parsed = datetime.fromisoformat(dt).replace(tzinfo=None if not dt.endswith("+00:00") else timezone.utc)
    parsed = datetime.fromisoformat(dt)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(IST).date()


def norm_rider(rid: str) -> str:
    """R7 -> R007, r19 -> R019, R003 -> R003."""
    m = re.match(r"^[Rr](0*)(\d+)$", rid.strip())
    if not m:
        return rid.strip().upper()
    return f"R{int(m.group(2)):03d}"


def clean_distance(d: str) -> Decimal:
    val = Decimal(d)
    if val >= 100:
        return val / 1000
    return val


def trip_fare(distance_km: Decimal, surge: Decimal) -> int:
    raw = (Decimal(25) + Decimal(6) * max(Decimal(0), distance_km - Decimal(2))) * surge
    return int(raw.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def main() -> None:
    riders = list(csv.DictReader(open(DATA / "riders.csv")))
    trips = list(csv.DictReader(open(DATA / "trips.csv")))
    lines = list(csv.DictReader(open(DATA / "payout_lines.csv")))

    print("bad rider_ids in trips.csv:", sorted({norm_rider(t["rider_id"]) for t in trips if t["rider_id"] != norm_rider(t["rider_id"])}))
    print("normalized rider mismatch rows:", sum(1 for t in trips if t["rider_id"] != norm_rider(t["rider_id"])))
    big = [t for t in trips if Decimal(t["distance_km"]) >= 100]
    print("corrupt-distance rows (>=100):", len(big), "min:", min(Decimal(t['distance_km']) for t in big), "max:", max(Decimal(t['distance_km']) for t in big))
    mid = [t["distance_km"] for t in trips if 20 < Decimal(t["distance_km"]) < 100]
    print("distances in (20,100):", len(mid), mid[:20])

    for t in trips:
        t["nrider"] = norm_rider(t["rider_id"])
        t["_ist_day"] = ist_day(t["started_at"])
        t["_dist"] = clean_distance(t["distance_km"])
        t["_surge"] = Decimal(t["surge_multiplier"])

    trips_by_id = {t["trip_id"]: t for t in trips}
    trip_lines: dict[str, list] = defaultdict(list)
    penalties = defaultdict(list)
    incentives = defaultdict(list)
    for ln in lines:
        rid, pd = norm_rider(ln["rider_id"]), date.fromisoformat(ln["payout_date"])
        if ln["line_type"] == "trip":
            trip_lines[ln["trip_id"]].append(ln)
        elif ln["line_type"] == "cancellation_penalty":
            penalties[(rid, pd)].append(ln)
        elif ln["line_type"] == "daily_incentive":
            incentives[(rid, pd)].append(ln)

    completed = defaultdict(list)
    for t in sorted(trips, key=lambda t: t["started_at"]):
        if t["status"] == "completed":
            completed[(t["nrider"], t["_ist_day"])].append(t)

    fare_mismatch = []
    unpaid_completed = []
    for (rid, day), ts_ in sorted(completed.items()):
        for t in ts_:
            expected = trip_fare(t["_dist"], t["_surge"])
            ln = trip_lines.get(t["trip_id"])
            if ln is None:
                unpaid_completed.append((rid, str(day), t["trip_id"], expected))
                continue
            actual = int(ln[0]["amount"])
            if actual != expected:
                fare_mismatch.append({"rider": rid, "day": str(day), "trip": t["trip_id"],
                                      "expected": expected, "actual": actual, "diff": expected - actual,
                                      "rawdist": t["distance_km"], "dist": str(t["_dist"]), "surge": t["surge_multiplier"]})

    print(f"\nTRUE unpaid completed: {len(unpaid_completed)}")
    for r in unpaid_completed:
        print("  UNPAID", r)
    print(f"\nTRUE fare mismatches: {len(fare_mismatch)}")
    for m in fare_mismatch:
        print("  MISMATCH", m)

    pen_issues = []
    for (rid, day), pls in sorted(penalties.items()):
        cancels = sum(1 for t in trips if t["nrider"] == rid and t["status"] == "cancelled_by_rider" and t["_ist_day"] == day)
        if len(pls) != cancels:
            pen_issues.append({"rider": rid, "day": str(day), "lines": len(pls), "cancels": cancels})
    print(f"\nTrue penalty issues: {len(pen_issues)}")
    for p in pen_issues:
