"""IST timezone helpers. IST is fixed UTC+05:30 (no DST) — a constant shift."""
from __future__ import annotations

from datetime import date, datetime, timedelta, timezone

IST = timezone(timedelta(hours=5, minutes=30))
UTC = timezone.utc


def to_ist(dt: datetime) -> datetime:
    """Convert a datetime (any tz or naive-UTC) to IST."""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return dt.astimezone(IST)


def utc_now() -> datetime:
    return datetime.now(tz=UTC)


def now_iso() -> str:
    """ISO-8601 trace timestamp with offset."""
    return datetime.now(tz=UTC).isoformat()


def parse_incoming(ts: str) -> datetime:
    """Parse a WhatsApp received_at like '2026-09-22T09:05:00+05:30'."""
    return datetime.fromisoformat(ts.strip())


def ist_day(ts: str) -> date:
    """Calendar day (IST) of an incoming message timestamp."""
    return to_ist(parse_incoming(ts)).date()


def trip_day(started_at_utc: str) -> date:
    """Calendar day (IST) of a trip started_at like '2026-09-12T02:30:00Z'."""
    dt = started_at_utc.strip()
    if dt.endswith("Z"):
        dt = dt[:-1] + "+00:00"
    return to_ist(datetime.fromisoformat(dt)).date()

"""Engine + session factory, startup data loading (bulk, idempotent by file checksum)."""
from __future__ import annotations

import csv
import hashlib
import logging
import os
from datetime import datetime
from pathlib import Path

from sqlalchemy import create_engine, insert, text
from sqlalchemy.orm import Session, sessionmaker

from . import policy
from .models import Base, Conversation, LoaderState, PayoutLine, Rider, TraceStep, Trip
from .tz import trip_day, utc_now

log = logging.getLogger("qd.db")

_engine = None
_SessionLocal = None


def get_engine():
    global _engine, _SessionLocal
    if _engine is None:
        url = os.environ.get("DATABASE_URL", "sqlite:///./qd_dev.db")
        if url.startswith("postgres://"):
            url = url.replace("postgres://", "postgresql://", 1)
        if url.startswith("postgresql://"):
            url = url.replace("postgresql://", "postgresql+psycopg://", 1)
        _engine = create_engine(url, pool_pre_ping=True, future=True)
        _SessionLocal = sessionmaker(bind=_engine, expire_on_commit=False, future=True)
    return _engine


def session() -> Session:
    get_engine()
    assert _SessionLocal is not None
    return _SessionLocal()


def _checksum(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()[:16]


def _unescape_ts(v: str) -> datetime:
    dt = v.strip().replace("Z", "+00:00")
    return datetime.fromisoformat(dt)


def load_csvs(data_dir: Path) -> dict:
    """Load riders/trips/payout_lines. Idempotent: keyed on file checksums; a restart
    with unchanged files is a no-op (fast boot). Rows are normalized at load time
    (rider-id normalization, IST day, duplicate-row flagging)."""
    get_engine()
    Base.metadata.create_all(_engine)
    loaded = {}
    with session() as s:
        specs = [
            ("riders", Rider, data_dir / "riders.csv"),
            ("trips", Trip, data_dir / "trips.csv"),
            ("payout_lines", PayoutLine, data_dir / "payout_lines.csv"),
        ]
        seen_trip_ids: set[str] = set()
        for name, model, path in specs:
            if not path.exists():
                raise FileNotFoundError(path)
            ck = _checksum(path)
            prior = s.get(LoaderState, name)
            if prior is not None and prior.checksum == ck:
                loaded[name] = prior.rows
                continue
            if prior is not None:  # changed files: wipe & reload
                s.query(model).delete()
            rows = []
            if name == "riders":
                for r in csv.DictReader(open(path, encoding="utf-8")):
                    rows.append({"rider_id": r["rider_id"], "name": r["name"], "city": r["city"],
                                 "joined_on": datetime.strptime(r["joined_on"], "%Y-%m-%d").date()})
            elif name == "trips":
                for r in csv.DictReader(open(path, encoding="utf-8")):
                    rows.append({
                        "trip_id": r["trip_id"], "rider_id": r["rider_id"],
                        "norm_rider_id": policy.norm_rider_id(r["rider_id"]),
                        "started_at": _unescape_ts(r["started_at"]),
                        "ist_day": trip_day(r["started_at"]),
                        "status": r["status"], "distance_km": r["distance_km"],
                        "surge_multiplier": r["surge_multiplier"],
                        "is_duplicate": 1 if r["trip_id"] in seen_trip_ids else 0,
                    })
                    seen_trip_ids.add(r["trip_id"])
            else:
                for r in csv.DictReader(open(path, encoding="utf-8")):
                    rows.append({
                        "line_id": r["line_id"], "payout_date": datetime.strptime(r["payout_date"], "%Y-%m-%d").date(),
                        "rider_id": r["rider_id"], "norm_rider_id": policy.norm_rider_id(r["rider_id"]),
                        "line_type": r["line_type"], "trip_id": r["trip_id"] or None,
                        "amount": int(r["amount"]),
                    })
            if rows:
                s.execute(insert(model), rows)
            s.merge(LoaderState(name=name, checksum=ck, rows=len(rows), loaded_at=utc_now()))
            loaded[name] = len(rows)
        s.commit()
    log.info("data loaded: %s", loaded)
    return loaded


def data_ready() -> bool:
    """Health only when the riders table actually has rows."""
    try:
        with session() as s:
            n = s.execute(text("select count(*) from riders")).scalar()
            return bool(n)
    except Exception:
        return False

"""Data access over the loaded CSV tables."""
from __future__ import annotations

from datetime import date

from sqlalchemy import select
from sqlalchemy.orm import Session

from .models import PayoutLine, PendingOp, Rider, Trip


def get_rider(s: Session, rider_id: str) -> Rider | None:
    return s.get(Rider, rider_id)


def trips_for_rider(s: Session, rider_id: str) -> list[Trip]:
    """All trips filed under this rider's normalized id, ordered by start time.
    Duplicate rows (same trip_id appearing twice) collapse into one in Python."""
    rows = s.execute(select(Trip).where(Trip.norm_rider_id == rider_id).order_by(Trip.started_at)).scalars().all()
    seen: set[str] = set()
    out = []
    for t in rows:
        if t.trip_id in seen or t.is_duplicate:
            if t.trip_id in seen:
                continue
        seen.add(t.trip_id)
        out.append(t)
    return out


def trips_for_day(s: Session, rider_id: str, day: date) -> list[Trip]:
    rows = (s.execute(select(Trip).where(Trip.norm_rider_id == rider_id, Trip.ist_day == day)
                      .order_by(Trip.started_at)).scalars().all())
    seen: set[str] = set()
    out = []
    for t in rows:
        if t.trip_id in seen:
            continue
        seen.add(t.trip_id)
        out.append(t)
    return out


def distinct_completed_trips_for_day(s: Session, rider_id: str, day: date) -> list[Trip]:
    return [t for t in trips_for_day(s, rider_id, day) if t.status == "completed"]


def trip_by_id(s: Session, trip_id: str) -> Trip | None:
    rows = s.execute(select(Trip).where(Trip.trip_id == trip_id)).scalars().all()
    if not rows:
        return None
    return rows[0]


def payout_line_for_trip(s: Session, trip_id: str) -> PayoutLine | None:
    rows = s.execute(select(PayoutLine).where(PayoutLine.trip_id == trip_id,
                                              PayoutLine.line_type == "trip")).scalars().all()
    return rows[0] if rows else None


def trip_lines_for_rider_day(s: Session, rider_id: str, day: date) -> dict[str, PayoutLine]:
    rows = (s.execute(select(PayoutLine).where(PayoutLine.norm_rider_id == rider_id,
                                               PayoutLine.payout_date == day,
                                               PayoutLine.line_type == "trip")).scalars().all())
    return {ln.trip_id: ln for ln in rows}


def penalty_lines(s: Session, rider_id: str, day: date) -> list[PayoutLine]:
    return list(s.execute(select(PayoutLine).where(PayoutLine.norm_rider_id == rider_id,
                                                   PayoutLine.payout_date == day,
                                                   PayoutLine.line_type == "cancellation_penalty")).scalars().all())


def incentive_lines(s: Session, rider_id: str, day: date) -> list[PayoutLine]:
    return list(s.execute(select(PayoutLine).where(PayoutLine.norm_rider_id == rider_id,
                                                   PayoutLine.payout_date == day,
                                                   PayoutLine.line_type == "daily_incentive")).scalars().all())


def pending_ops_for_rider(s: Session, rider_id: str) -> list[PendingOp]:
    return list(s.execute(select(PendingOp).where(PendingOp.rider_id == rider_id,
                                                  PendingOp.status == "pending")).scalars().all())

"""Intent parsing — deterministic, no LLM required. Understands the Hinglish shapes
riders use in data/conversations.json plus generic English variants. An optional LLM
layer (app/llm.py) can refine this, but the parser alone must handle everything.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import date, datetime, timedelta

from .tz import to_ist

_TRIP_RE = re.compile(r"\bT(\d{5,7})\b")
_RIDER_RE = re.compile(r"\bR\s?(\d{1,3})\b")

INJECTION_MARKERS = ("system:", "system message", "ignore all previous", "ignore the above",
                     "new instructions", "developer mode", "jailbreak", "prompt")
_RIDER_RE2 = _RIDER_RE


@dataclass
class Claim:
    kind: str                      # surge|distance|missing_payment|incentive|penalty|fare
    day: date | None
    trip_ids: list[str] = field(default_factory=list)


@dataclass
class Intent:
    language: str                  # hinglish | english
    claims: list[Claim]
    impersonation: bool = False
    injection: bool = False
    referenced_others: list[str] = field(default_factory=list)
    vague: bool = False
    raw: str = ""


_MONTHS = {"jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6, "jul": 7, "aug": 8,
           "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12, "january": 1, "february": 2,
           "march": 3, "april": 4, "june": 6, "july": 7, "august": 8, "october": 10,
           "november": 11, "december": 12}


def _event_days(text: str, received_ist: datetime) -> list[tuple[int, str]]:
    """Day-of-month candidates with their surrounding marker words."""
    out = []
    t = text.lower()
    for m in re.finditer(r"(\d{1,2})\s*(?:tarikh|tareekh|wala|wali|th|st|nd|rd)?\s*(?:ko|ka|ke|of)?",
                         t):
        d = int(m.group(1))
        if 1 <= d <= 31:
            out.append((d, m.group(0)))
    for m in re.finditer(r"(?:tarikh|wala|tarikh)\s*(\d{1,2})\b", t):
        d = int(m.group(1))
        if 1 <= d <= 31:
            out.append((d, m.group(0)))
    return out


def _extract_dates(text: str, received_ist: datetime) -> list[date]:
    t = text.lower()
    days: list[date] = []
    todays_year, todays_month = received_ist.year, received_ist.month
    # explicit month + day: "sep 19", "19 sept", "sept 19", "19 sept ke"
    for m in re.finditer(r"(?:(sep|sept|september|january|february|march|april|may|june|july|august|"
                         r"october|november|december)\s+(\d{1,2}))|(?:(\d{1,2})\s*(?:tarikh|tareekh)?\s+"
                         r"(?:sept|sep|september)\b)", t):
        if m.group(2):
            mon = _MONTHS.get(m.group(1).lower(), todays_month)
            day = int(m.group(2))
        else:
            mon = 9
            day = int(m.group(3))
        if 2000 <= day <= 2100:  # not a day — looks like a year
            continue
        try:
            days.append(date(todays_year, mon, day))
        except ValueError:
            continue
    # day + ko/tarikh/wala/ka/ke + sept at end handled; now plain "18 ko", "20 wala", "19th"
    for m in re.finditer(r"\b(\d{1,2})\s*(?:tarikh|tareekh|wala|wali)?\s*(?:ko|ka|ke|th|st|nd|rd)\b",
                         t):
        d = int(m.group(1))
        if 1 <= d <= 31 andTodays := True:
            try:
                days.append(date(todays_year, todays_month, d))
            except ValueError:
                continue
    for m in re.finditer(r"\b(\d{1,2})\s*(?:tarikh|tareekh)\b", t):
        d = int(m.group(1))
        if 1 <= d <= 31:
            try:
                days.append(date(todays_year, todays_month, d))
            except ValueError:
                continue
    # relative days
    if re.search(r"\bkal\b|\byesterday\b", t):
        days.append(received_ist.date() - timedelta(days=1))
    if re.search(r"\baaj\b|\btoday\b", t):
        days.append(received_ist.date())
    return sorted(set(days))


def _kinds(text: str) -> set[str]:
    t = text.lower()
    kinds: set[str] = set()
    if "surge" in t:
        kinds.add("surge")
    if "incentiv" in t or re.search(r"\b12\s*(?:order|trip|rides)\b", t) or "12 se zyada" in t or "12 se badhkar" in t or "12 kiye" in t or "12 complete" in t or "12+" in t:
        kinds.add("incentive")
    if "penalt" in t or ("cancel" in t and ("kata" in t or "kat" in t)):
        kinds.add("penalty")
    if re.search(r"payment nahi aaya|payment nahi mila|paisa nahi aaya|paisa nahi mila|paisa hi nahi|"
                 r"paisa kam aaya|payment missing|paisa missing|nahi aaya", t):
        # generic missing -> only if no narrower claim matched
        if not kinds:
            kinds.add("missing_payment")
        else:
            kinds.add("missing_payment")
    if "distance" in t or re.search(r"\bkm\b", t) or "kilometre" in t or "kilometer" in t:
        kinds.add("distance")
    if not kinds and re.search(r"payout (galat|kam|wrong|kam aaya)|payout sahi|payout galat", t):
        kinds.add("fare")
    return kinds


def parse(text: str, received_at: str) -> Intent:
    received_ist = to_ist(datetime.fromisoformat(received_at))
    low = text.lower().strip()

    trip_ids = [f"T{m.group(1)}" for m in _TRIP_RE.finditer(text)]
    others = []
    for m in _RIDER_RE2.finditer(text):
        cand = f"R{int(m.group(1)):03d}"
        if cand != "__NONE__" and _RIDER_RE2.pattern and cand not in others:
            others.append(cand)

    logs = []
    injection = any(marker in low for marker in INJECTION_MARKERS)
    impersonation = False
    from .policy import norm_rider_id
    # caller bound to one rider; references to other rider ids are impersonation attempts
    # (the caller's own id is never in the text; conversations.json examples never name self)
    if others:
        referenced = [o for o in others if o != norm_rider_id(text)]
        # "mera" style self-references aren't detectable here; caller id arrives out-of-band

    language = "english"
    if re.search(r"\b(bhai|yaar|nahi|mila|kata|kiye|karo|kaata|banda|thik|nahi mila|karo)\b", low):
        language = "hinglish"

    kinds = _kinds(low)
    dates = _extract_dates(low, received_ist)

    # vague: complain words but no date, no trip, and no precise topic keyword
    vague = False
    if not trip_ids and not dates and not kinds:
        vague = True
    if re.search(r"payout galat|payout kam|payout sahi nahi|kam aaya hai|galat aaya", low) and not kinds and not dates and not trip_ids:
        vague = True

    claims: list[Claim] = []
    if trip_ids:
        claims.append(Claim(kind=kinds.pop() if kinds else "fare", day=None, trip_ids=trip_ids))
        # a named trip usually carries its own date too: attach same kinds to it not needed
    for d in dates:
        for k in (sorted(kinds) or ["fare"]):
            claims.append(Claim(kind=k, day=d))
    if not claims and not trip_ids and kinds and not vague:
        # topic without date -> cannot investigate, needs one question back
        claims.append(Claim(kind=sorted(kinds)[0], day=None))

    return Intent(language=language, claims=claims, impersonation=bool(others),
                  injection=injection, referenced_others=others, vague=vague, raw=text)

"""Deterministic dispute investigation. Pure code — the LLM never computes money.

investigate() takes one claim (kind + IST day and/or named trip_ids) for a bound rider
and returns items (each with a stable dispute_id) plus human-readable facts that the
reply templates (or LLM) use verbatim. Amounts are recomputed from policy.py at
resolution time — items carry evidence, not trust.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import date

from sqlalchemy.orm import Session

from . import policy, repo
from .models import Trip


@dataclass
class Item:
    id: str            # stable: "trip:T123456", "incentive:2026-09-21", "penalty_dup:2026-09-18"
    type: str          # underpaid | unpaid | incentive_missing | penalty_dup
    trip_id: str | None
    day: date | None
    expected: int
    actual: int
    diff: int          # owed rupees


@dataclass
class Facts:
    """Plain facts for the reply builder (no LLM creativity needed on numbers)."""
    trips_done: int | None = None                      # distinct completed trips that day
    incentive_paid: int | None = None                  # incentive line amount if paid, else None
    incentive_eligible: bool | None = None
    penalty_lines: int | None = None
    rider_cancels: int | None = None
    surge_multiplier: float | None = None
    trip_distance: float | None = None
    trip_status: str | None = None
    note: str | None = None


@dataclass
class Investigation:
    items: list[Item] = field(default_factory=list)
    facts: Facts = field(default_factory=Facts)
    blocked: str | None = None        # set if we cannot act: "not_yours" | "out_of_window" | "trip_not_found"
    owed: int = 0

    @property
    def has_items(self) -> bool:
        return bool(self.items)


def _trip_item(trip: Trip, paid: int | None, kind: str) -> Item | None:
    expected = policy.trip_fare(trip.distance_km, trip.surge_multiplier)
    actual = paid if paid is not None else 0
    diff = expected - actual
    if diff <= 0:
        return None
    if kind == "surge" and (trip.surge_multiplier or "1.0") == "1.0":
        return None  # a surge claim on a trip with surge 1.0 has nothing owed
    if kind == "distance" and (trip.surge_multiplier or "1.0") != "1.0":
        return None
    return Item(id=f"trip:{trip.trip_id}", type=("unpaid" if paid is None else "underpaid"),
                trip_id=trip.trip_id, day=trip.ist_day, expected=expected, actual=actual, diff=diff)


def _investigate_trip(s: Session, rider_id: str, trip_id: str, kind: str) -> Investigation:
    inv = Investigation()
    trip = repo.trip_by_id(s, trip_id)
    if trip is None:
        inv.blocked = "trip_not_found"
        return inv
    inv.facts.trip_status = trip.status
    inv.facts.surge_multiplier = float(trip.surge_multiplier)
    inv.facts.trip_distance = float(policy.clean_distance(trip.distance_km))
    if trip.norm_rider_id != rider_id:
        # access control: the trip ledger belongs to a different account
        inv.blocked = "not_yours"
        return inv
    line = repo.payout_line_for_trip(s, trip_id)
    if trip.status != "completed":
        inv.facts.note = "cancelled"
        if kind == "penalty" and trip.status == "cancelled_by_rider":
            # cancelled trips earn nothing; the 10 penalty is per policy
            inv.facts.note = "cancelled_penalty"
        return inv
    item = _trip_item(trip, int(line.amount) if line else None, kind)
    if item:
        inv.items.append(item)
        inv.owed += item.diff
    else:
        inv.facts.note = "paid_correct" if line else "unpaid_but_zero"
    return inv


def _investigate_day(s: Session, rider_id: str, day: date, kind: str) -> Investigation:
    inv = Investigation()
    trips = repo.trips_for_day(s, rider_id, day)
    lines = repo.trip_lines_for_rider_day(s, rider_id, day)

    kinds = {kind} if kind != "fare" else {"fare", "missing_payment"}
    if kind == "fare":
        kinds = {"fare", "missing_payment"}

    if "fare" in kinds or "missing_payment" in kinds:
        for t in trips:
            if t.status != "completed":
                continue
            paid = int(lines[t.trip_id].amount) if t.trip_id in lines else None
            item = _trip_item(t, paid, kind if kind in ("surge", "distance") else "fare")
            if item:
                inv.items.append(item)
                inv.owed += item.diff

    if kind == "incentive":
        completed = [t for t in trips if t.status == "completed"]
        count = len(completed)  # trips_for_day already deduplicates trip_ids
        inv.facts.trips_done = count
        eligible = policy.is_eligible_incentive_day(count)
        inv.facts.incentive_eligible = eligible
        inc = repo.incentive_lines(s, rider_id, day)
        inv.facts.incentive_paid = int(inc[0].amount) if inc else None
        if eligible and not inc:
            item = Item(id=f"incentive:{day}", type="incentive_missing", trip_id=None, day=day,
                        expected=policy.INCENTIVE_AMOUNT, actual=0, diff=policy.INCENTIVE_AMOUNT)
            inv.items.append(item)
            inv.owed += item.diff
        elif inc and policy.INCENTIVE_AMOUNT in [int(x.amount) for x in inc]:
            inv.facts.note = "incentive_paid"

    if kind == "penalty":
        pls = repo.penalty_lines(s, rider_id, day)
        cancels = len([t for t in trips if t.status == "cancelled_by_rider"])
        inv.facts.penalty_lines = len(pls)
        inv.facts.rider_cancels = cancels
        refund = policy.penalty_refund(len(pls), cancels)
        if refund > 0:
            item = Item(id=f"penalty_dup:{day}", type="penalty_dup", trip_id=None, day=day,
                        expected=refund, actual=0, diff=refund)
            inv.items.append(item)
            inv.owed += item.diff
        elif len(pls) == cancels and cancels > 0:
            inv.facts.note = "penalty_correct"
    return inv


def investigate_claim(s: Session, rider_id: str, claim) -> Investigation:
    if claim.trip_ids:
        trip_id = claim.trip_ids[0]
        if claim.day:
            trip = repo.trip_by_id(s, trip_id)
            if trip is not None and trip.norm_rider_id == rider_id:
                return _investigate_trip(s, rider_id, trip_id, claim.kind)
            if trip is not None and trip.norm_rider_id != rider_id:
                # try day scan too — data can hold the trip under another id's file row
                day_inv = _investigate_day(s, rider_id, claim.day, claim.kind)
                if day_inv.items:
                    return day_inv
        return _investigate_trip(s, rider_id, trip_id, claim.kind)
    if claim.day:
        return _investigate_day(s, rider_id, claim.day, claim.kind)
    return Investigation(blocked="need_details")

"""PaySwift sandbox client — deterministic wrapper around POST/GET /v1/payouts.

Every payout call carries a deterministic Idempotency-Key (rider + day + covered
discrepancy ids), so a timeout-then-retry, or a second approve click, cannot pay twice.
"""
from __future__ import annotations

import asyncio
import hashlib
import json
import logging
import os

import httpx

log = logging.getLogger("qd.payswift")

RETRY_STATUS = {429, 500, 502, 503, 504}


class PaySwiftError(Exception):
    def __init__(self, status: int, body: str):
        super().__init__(f"payswift {status}: {body[:200]}")
        self.status = status
        self.body = body


def idempotency_key(rider_id: str, day, covered_ids: list[str]) -> str:
    payload = json.dumps({"r": rider_id, "d": str(day), "ids": sorted(covered_ids)}, sort_keys=True)
    return f"qd-{rider_id}-{day}-" + hashlib.sha256(payload.encode()).hexdigest()[:16]


class PaySwift:
    def __init__(self, base_url: str | None = None):
        self.base_url = (base_url or os.environ.get("PAYSWIFT_BASE_URL", "http://payswift:8081")).rstrip("/")
        self._client = httpx.AsyncClient(base_url=self.base_url, timeout=12.0)

    async def aclose(self) -> None:
        await self._client.aclose()

    async def payout(self, rider_id: str, amount: int, reference: str, idem_key: str) -> dict:
        """POST /v1/payouts with a deterministic Idempotency-Key. Retries only on the
        idempotent-safe statuses; a 409 means this exact payout was already accepted."""
        body = {"rider_id": rider_id, "amount": amount, "reference": reference}
        last = None
        for attempt in range(4):
            try:
                r = await self._client.post(
                    "/v1/payouts", json=body,
                    headers={"Idempotency-Key": idem_key})
                if r.status_code in (200, 201):
                    return r.json()
                if r.status_code == 409:
                    # same key already used — treat as already issued
                    try:
                        existing = await self.list_payouts(rider_id)
                        return {"payout_id": (existing[-1].get("payout_id") if existing else None),
                                "status": "paid", "duplicate": True}
                    except Exception:
                        return {"payout_id": None, "status": "paid", "duplicate": True}
                if r.status_code in RETRY_STATUS:
                    last = PaySwiftError(r.status_code, r.text)
                    await asyncio.sleep(1.0 * (attempt + 1))  # 1,2,3s backoff
                    continue
                raise PaySwiftError(r.status_code, r.text)
            except (httpx.TimeoutException, httpx.ConnectError) as e:
                last = e
                await asyncio.sleep(1.0 * (attempt + 1))
        raise last if last is not None else PaySwiftError(0, "unknown")

    async def list_payouts(self, rider_id: str | None = None) -> list[dict]:
        params = {"rider_id": rider_id} if rider_id else {}
        r = await self._client.get("/v1/payouts", params=params)
        if r.status_code != 200:
            raise PaySwiftError(r.status_code, r.text)
        body = r.json()
        return body if isinstance(body, list) else body.get("payouts", [])

    async def health(self) -> bool:
        try:
            r = await self._client.get("/health")
            return r.status_code == 200
        except httpx.HTTPError:
            return False

